import java.io.*;
import java.util.*;

public class Main {
    static long[] pow10 = new long[20];
    static {
        pow10[0] = 1L;
        for (int i = 1; i < 20; i++) {
            pow10[i] = pow10[i - 1] * 10L;
        }
    }

    // 将 k 位整数 a 按十进制反转
    static long revInt(long a, int k) {
        long r = 0;
        for (int i = 0; i < k; i++) {
            r = r * 10 + a % 10;
            a /= 10;
        }
        return r;
    }

    // 构造 A + rev(A) + A
    static long makeNum(long a, int k) {
        return a * pow10[2 * k] + revInt(a, k) * pow10[k] + a;
    }

    // 统计 <= x 的双镜数个数
    static long countLeq(long x) {
        if (x < 0) return 0;
        int n = Long.toString(x).length();
        long ans = 0;
        for (int k = 1; k <= 6; k++) {
            if (3 * k < n) {
                ans += 9L * pow10[k - 1];
            } else if (3 * k == n) {
                long lo = pow10[k - 1];
                long hi = pow10[k] - 1;
                long L = lo, R = hi, best = lo - 1;
                while (L <= R) {
                    long mid = (L + R) >>> 1;
                    long v = makeNum(mid, k);
                    if (v <= x) {
                        best = mid;
                        L = mid + 1;
                    } else {
                        R = mid - 1;
                    }
                }
                if (best >= lo) {
                    ans += best - lo + 1;
                }
            }
        }
        return ans;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < T; t++) {
            String[] parts = br.readLine().trim().split("\\s+");
            long l = Long.parseLong(parts[0]);
            long r = Long.parseLong(parts[1]);
            sb.append(countLeq(r) - countLeq(l - 1)).append('\n');
        }
        System.out.print(sb.toString());
    }
}
